// WHO IS ACTUALLY BEHIND THESE EMAILS? Classifies every send-ready contact by the
// email local-part, then cross-tabs against company size - because at a 1-4 person
// installer, info@ IS the owner's inbox, while at a 50+ firm it is a receptionist.
try {
  var v = ($input.first().json || {}).values || [];
  if (v.length < 2) { return [{ json: { error: 'no rows' } }]; }
  var H = v[0], I = {};
  for (var h = 0; h < H.length; h++) { I[String(H[h]).trim()] = h; }
  function c(r, n) { var i = I[n]; if (i === undefined) { return ''; } var x = r[i]; return (x === undefined || x === null) ? '' : String(x).trim(); }
  function T(x) { var s = String(x).toLowerCase(); return s === 'true' || s === 'yes' || s === '1'; }

  var GEN = ['info','sales','enquiries','enquiry','admin','contact','hello','office','accounts','mail','support','team','service','post','general','bookings','booking','reception','help','hi','enquires','customerservice','estimating','quotes'];

  function localPart(e) { var s = String(e || ''); var a = s.indexOf('@'); return a > -1 ? s.substring(0, a).toLowerCase() : ''; }
  function classify(e) {
    var lp = localPart(e);
    if (!lp) { return 'no-email'; }
    for (var i = 0; i < GEN.length; i++) { if (lp === GEN[i]) { return 'role-inbox'; } }
    // first.last / first_last / first-last
    if (/^[a-z]{2,14}[._-][a-z]{2,14}$/.test(lp)) { return 'named-person'; }
    // single short alphabetic token = almost always a first name
    if (/^[a-z]{2,14}$/.test(lp)) { return 'named-person'; }
    // contains a role word but is not exactly one, e.g. sales.uk, info2
    for (var g = 0; g < GEN.length; g++) { if (lp.indexOf(GEN[g]) !== -1) { return 'role-inbox'; } }
    return 'other';
  }

  var byClass = {}, bySizeClass = {}, sendReady = 0;
  var namedWithFirstName = 0, roleWithFirstName = 0;
  var hasWebsite = 0, roleWithWebsite = 0;
  var smallFirmRole = 0, largeFirmRole = 0;
  var samples = { named: [], role: [], other: [] };

  for (var r = 1; r < v.length; r++) {
    var row = v[r];
    if (c(row, 'Email') === '' || T(c(row, 'PECR Risk')) || !T(c(row, 'Emailable'))) { continue; }
    sendReady++;

    var cls = classify(c(row, 'Email'));
    byClass[cls] = (byClass[cls] || 0) + 1;

    var tier = c(row, 'Size Tier') || '(blank)';
    if (!bySizeClass[tier]) { bySizeClass[tier] = {}; }
    bySizeClass[tier][cls] = (bySizeClass[tier][cls] || 0) + 1;

    var fn = c(row, 'First Name') !== '';
    if (cls === 'named-person' && fn) { namedWithFirstName++; }
    if (cls === 'role-inbox' && fn) { roleWithFirstName++; }

    var web = c(row, 'Website') !== '';
    if (web) { hasWebsite++; }
    if (cls === 'role-inbox' && web) { roleWithWebsite++; }

    // Tier strings look like '1 - 0-4', '3 - 15-49'
    if (cls === 'role-inbox') {
      var t0 = tier.charAt(0);
      if (t0 === '0' || t0 === '1' || t0 === '2') { smallFirmRole++; }
      else if (t0 === '3' || t0 === '4' || t0 === '5' || t0 === '6') { largeFirmRole++; }
    }

    if (cls === 'named-person' && samples.named.length < 4) { samples.named.push(c(row, 'Email')); }
    if (cls === 'role-inbox' && samples.role.length < 4) { samples.role.push(c(row, 'Email')); }
    if (cls === 'other' && samples.other.length < 4) { samples.other.push(c(row, 'Email')); }
  }

  return [{ json: {
    sendReady: sendReady,
    byContactType: byClass,
    pctNamedPerson: Math.round((byClass['named-person'] || 0) / sendReady * 1000) / 10,
    pctRoleInbox: Math.round((byClass['role-inbox'] || 0) / sendReady * 1000) / 10,
    roleInboxBySize: { atSmallFirms_0to14: smallFirmRole, atLargerFirms_15plus: largeFirmRole, note: 'At a 0-14 person installer a role inbox is normally read by the owner. At 15+ it is more likely staff.' },
    firstNameCoverage: { onNamedPerson: namedWithFirstName, onRoleInbox: roleWithFirstName },
    enrichmentCeiling: { hasWebsite: hasWebsite, roleInboxWithWebsite: roleWithWebsite, note: 'roleInboxWithWebsite is the ONLY population Instantly Lead Finder could improve - it needs a domain to search, and a named contact already has one.' },
    samples: samples
  }}];
} catch (e) { return [{ json: { error: 'failed: ' + e.message } }]; }
